"""Comparison report (spec 7.8): Markdown generated by Python from scores, call records and
faults. Nothing here calls a model; every figure is derived from the records handed in, in
``Decimal``, and the output is deterministic (fixed orders, no set or dict iteration)."""

from __future__ import annotations

from collections.abc import Sequence
from datetime import timedelta
from decimal import ROUND_HALF_UP, Context, Decimal, localcontext

from deploy_vii.contracts import PATHWAY_MODULES, PathwayId
from deploy_workflow.model.record import CallRecord
from deploy_workflow.model_testing.budget import (
    Runs,
    Settlement,
    _key,
    account_spend,
    settled_amounts,
)
from deploy_workflow.model_testing.configs import ACCOUNTS, CASES, CONFIGS
from deploy_workflow.model_testing.faults import FaultRecord
from deploy_workflow.model_testing.pathway import PathwayScore
from deploy_workflow.model_testing.records import RunMeta
from deploy_workflow.model_testing.scoring import ModuleScore

_WIDE = Context(prec=120, rounding=ROUND_HALF_UP)
_MATCHED = frozenset({"match", "conflict_ok", "gap_ok"})
_UNSCORED = frozenset({"unmapped", "inherited"})
_FAULT_CLASSES = ("product", "prompt", "harness", "model")
_OFFLINE_BANNER = "Offline runs are included: their costs are computed from recordings, not money."


def _quantise(value: Decimal, exp: str) -> Decimal:
    return value.quantize(Decimal(exp), rounding=ROUND_HALF_UP, context=_WIDE)


def _money(value: Decimal) -> str:
    return f"${_quantise(value, '0.01')}"


def _seconds(value: Decimal) -> str:
    return f"{_quantise(value, '1')} s"


def _tokens_text(tokens: tuple[int, bool] | None) -> str:
    if tokens is None:
        return "n/r tok"
    total, partial = tokens
    return f"{'≥' if partial else ''}{_quantise(Decimal(total) / 1000, '0.1')}k tok"


def _cell_text(text: str) -> str:
    return " ".join(text.split()).replace("|", "\\|")


def _cost(records: Sequence[CallRecord]) -> tuple[Decimal, bool]:
    """Sum of settled cost, or the reservation where the cost is unknown; and whether any was."""
    total = Decimal(0)
    reserved = False
    for r in records:
        if r.settled_usd is None:
            total = _WIDE.add(total, r.reserved_usd)
            reserved = True
        else:
            total = _WIDE.add(total, r.settled_usd)
    return total, reserved


def _cost_text(records: Sequence[CallRecord]) -> str:
    total, reserved = _cost(records)
    return f"{_money(total)} reserved" if reserved else _money(total)


def _tokens(records: Sequence[CallRecord]) -> tuple[int, bool] | None:
    """Input + output + reasoning and whether it is only a lower bound (some field was not
    reported); ``None`` only when no record reported any of the three."""
    total: int | None = None
    partial = False
    for r in records:
        for part in (r.input_tokens, r.output_tokens, r.reasoning_tokens):
            if part is None:
                partial = True
            else:
                total = part if total is None else total + part
    return None if total is None else (total, partial)


def _wall(records: Sequence[CallRecord]) -> Decimal | None:
    """Seconds over records with both timestamps; ``None`` when no record has both."""
    micros: int | None = None
    for r in records:
        if r.finished_at is None:
            continue
        delta = r.finished_at - r.started_at
        if delta.days < 0:
            raise ValueError(
                f"run {r.run_id} module {r.module_id} call {r.call_index}: finished before started"
            )
        step = delta // timedelta(microseconds=1)
        micros = step if micros is None else micros + step
    return None if micros is None else _WIDE.divide(Decimal(micros), Decimal(1_000_000))


def _retries(records: Sequence[CallRecord]) -> int:
    """W8: a record is a retry when it is the first call of an attempt-1 step, or when the
    previous call of the same (run, module, step, attempt) has ``error_class`` set."""
    groups: dict[tuple[str, str, str, int], dict[int, CallRecord]] = {}
    for r in records:
        groups.setdefault((r.run_id, r.module_id, r.step_id, r.attempt), {})[r.call_index] = r
    count = 0
    for key in sorted(groups):
        calls = groups[key]
        first = min(calls)
        for index, r in sorted(calls.items()):
            before = calls.get(index - 1)
            if (key[3] == 1 and index == first) or (before is not None and before.error_class):
                count += 1
    return count


def _counts(module: ModuleScore) -> tuple[int, int, int, int]:
    """Matched, scored, inherited and refused facts. A refusal gap (``gap_ok`` on a refused
    module) stays scored but is not matched: the module produced nothing to compare."""
    refused = sum(
        1
        for f in module.facts
        if module.head_status == "refused"
        and f.outcome == "gap_ok"
        and (f.observed or "").startswith("refused:")
    )
    matched = sum(1 for f in module.facts if f.outcome in _MATCHED) - refused
    scored = sum(1 for f in module.facts if f.outcome not in _UNSCORED)
    inherited = sum(1 for f in module.facts if f.outcome == "inherited")
    return matched, scored, inherited, refused


def _cell(score: PathwayScore, module: ModuleScore, records: Sequence[CallRecord]) -> str:
    if score.outcome == "stopped":
        return _cell_text(f"STOPPED ({score.stopped_reason})")
    matched, scored, inherited, refused = _counts(module)
    head = f"{'PASS' if module.passed else 'FAIL'} {matched}/{scored}"
    if refused:
        head += f" ({refused} refused)"
    if inherited:
        head += f" ({inherited} inherited)"
    if score.render_problem is not None:
        head += " (render: " + _cell_text(score.render_problem) + ")"
    wall = _wall(records)
    parts = [
        head,
        _cost_text(records),
        _tokens_text(_tokens(records)),
        "n/r" if wall is None else _seconds(wall),
    ]
    return " · ".join(parts)


def _table(header: Sequence[str], rows: Sequence[Sequence[str]]) -> list[str]:
    lines = ["| " + " | ".join(header) + " |", "|" + "|".join(" --- " for _ in header) + "|"]
    lines.extend("| " + " | ".join(row) + " |" for row in rows)
    return lines


def _config_order(config_ids: set[str]) -> list[str]:
    unknown = sorted(c for c in config_ids if c not in CONFIGS)
    if unknown:
        raise ValueError(f"unknown config_id {unknown[0]}")
    return [c for c in CONFIGS if c in config_ids]


def _module_order(pathway: PathwayId, scores: Sequence[PathwayScore]) -> list[str]:
    plan = list(PATHWAY_MODULES[pathway])
    seen = set(plan)
    for s in scores:
        for m in s.modules:
            if m.module_id not in seen:
                seen.add(m.module_id)
                plan.append(m.module_id)
    present = {m.module_id for s in scores for m in s.modules}
    return [m for m in plan if m in present]


def _pathway_section(
    pathway: PathwayId, scores: Sequence[PathwayScore], by_run: dict[str, Sequence[CallRecord]]
) -> list[str]:
    by_config = {s.config_id: s for s in scores}
    configs = _config_order(set(by_config))
    rows: list[list[str]] = []
    for module_id in _module_order(pathway, scores):
        row = [module_id]
        for config_id in configs:
            score = by_config[config_id]
            found = next((m for m in score.modules if m.module_id == module_id), None)
            if found is None:
                row.append("—")
                continue
            records = [r for r in by_run[score.run_id] if r.module_id == module_id]
            row.append(_cell(score, found, records))
        rows.append(row)
    return [f"## {pathway} ({scores[0].case_id})", "", *_table(["Module", *configs], rows), ""]


def _percent(matched: int, scored: int) -> str:
    if scored == 0:
        return "n/a"
    value = _WIDE.divide(Decimal(matched) * 100, Decimal(scored))
    return f"{_quantise(value, '0.1')}% ({matched}/{scored})"


def _accuracy(matched: int, scored: int, stopped: int) -> str:
    """Accuracy of settled runs only: a stopped run produced nothing, and golden ``missing``
    facts pass on absent output, so its module scores are not an accuracy."""
    if stopped == 0:
        return _percent(matched, scored)
    if scored == 0:
        return f"n/a ({stopped} stopped)"
    return f"{_percent(matched, scored)}; {stopped} stopped"


def _median(values: Sequence[Decimal]) -> Decimal | None:
    if not values:
        return None
    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return _WIDE.divide(_WIDE.add(ordered[mid - 1], ordered[mid]), Decimal(2))


def _totals_section(scores: Sequence[PathwayScore], runs: Runs) -> list[str]:
    configs = _config_order({s.config_id for s in scores} | {m.config_id for m, _ in runs})
    rows: list[list[str]] = []
    for config_id in configs:
        matched = scored = stopped = 0
        for s in scores:
            if s.config_id != config_id:
                continue
            if s.outcome != "settled":
                stopped += 1
                continue
            for module in s.modules:
                m, n, _, _ = _counts(module)
                matched, scored = matched + m, scored + n
        mine = [(meta, records) for meta, records in runs if meta.config_id == config_id]
        records = [r for _, rs in mine for r in rs]
        live = [r for meta, rs in mine if meta.mode == "live" for r in rs]
        offline = [r for meta, rs in mine if meta.mode == "offline" for r in rs]
        walls = [w for w in (_wall(rs) for _, rs in mine) if w is not None]
        median = _median(walls)
        rows.append(
            [
                config_id,
                _accuracy(matched, scored, stopped),
                _cost_text(live),
                _cost_text(offline),
                _tokens_text(_tokens(records)),
                "n/r" if median is None else _seconds(median),
                str(_retries(records)),
            ]
        )
    header = [
        "Config",
        "Accuracy",
        "Cost (live)",
        "Cost (offline, computed)",
        "Tokens",
        "Median wall time",
        "Retries",
    ]
    return ["## Totals", "", *_table(header, rows), ""]


def _rerun(fault: FaultRecord) -> str:
    if fault.rerun_passed is None:
        return "none"
    return "passed" if fault.rerun_passed else "failed"


def _faults_section(faults: Sequence[FaultRecord]) -> list[str]:
    lines = ["## Faults by class", ""]
    for fault_class in _FAULT_CLASSES:
        mine = sorted((f for f in faults if f.fault_class == fault_class), key=_fault_key)
        lines.append(f"### {fault_class} ({len(mine)})")
        lines.append("")
        for f in mine:
            lines.append(
                f"- {f.fault_id} · {f.case_id} · {f.module_id} · {f.config_id}"
                f" · fix {f.fix_ref or '—'} · rerun: {_rerun(f)}"
            )
        if mine:
            lines.append("")
    return lines


def _fault_key(fault: FaultRecord) -> tuple[str, str, str]:
    return (fault.fault_id, fault.case_id, fault.module_id)


def _accounts_section(runs: Runs, settlements: Sequence[Settlement]) -> list[str]:
    rows: list[list[str]] = []
    for account_id, account in ACCOUNTS.items():
        spend = account_spend(runs, account_id, settlements)
        usable = account.usable
        rows.append(
            [
                account_id,
                _money(spend),
                _money(usable),
                _money(_WIDE.subtract(usable, spend)),
            ]
        )
    header = ["Account", "Spend (live runs)", "Usable", "Remaining"]
    return ["## Accounts", "", *_table(header, rows)]


def _agree(score: PathwayScore, meta: RunMeta) -> None:
    for field in ("config_id", "pathway", "case_id"):
        if getattr(score, field) != getattr(meta, field):
            raise ValueError(f"score for run {score.run_id}: {field} differs from its run")


def render_report(
    scores: Sequence[PathwayScore],
    runs: Runs,
    faults: Sequence[FaultRecord],
    settlements: Sequence[Settlement] = (),
) -> str:
    amounts = settled_amounts(runs, settlements)
    # A user-settled unknown charge counts at its settled amount in every cost figure.
    costed: Runs = [
        (
            meta,
            [
                r.model_copy(update={"settled_usd": amounts[_key(r)]}) if _key(r) in amounts else r
                for r in records
            ],
        )
        for meta, records in runs
    ]
    by_meta: dict[str, RunMeta] = {}
    by_run: dict[str, Sequence[CallRecord]] = {}
    for meta, records in costed:
        if meta.run_id in by_run:
            raise ValueError(f"duplicate run_id {meta.run_id}")
        by_meta[meta.run_id] = meta
        by_run[meta.run_id] = records
    seen: set[tuple[str, str]] = set()
    case_of: dict[str, str] = {}
    for s in scores:
        if (s.pathway, s.config_id) in seen:
            raise ValueError(f"duplicate score for {s.pathway} on {s.config_id}")
        seen.add((s.pathway, s.config_id))
        if s.pathway not in CASES:
            raise ValueError(f"score for unknown pathway {s.pathway}")
        if s.run_id not in by_run:
            raise ValueError(f"no run records for scored run {s.run_id}")
        _agree(s, by_meta[s.run_id])
        if case_of.setdefault(s.pathway, s.case_id) != s.case_id:
            raise ValueError(f"scores for {s.pathway} name different case_id values")

    lines: list[str] = []
    if any(meta.mode == "offline" for meta, _ in runs):
        lines += [_OFFLINE_BANNER, ""]
    lines += ["# Model comparison report", ""]
    with localcontext(_WIDE):
        for pathway in CASES:
            mine = [s for s in scores if s.pathway == pathway]
            if mine:
                lines += _pathway_section(pathway, mine, by_run)
        lines += _totals_section(scores, costed)
        lines += _faults_section(faults)
        lines += _accounts_section(runs, settlements)
    return "\n".join(lines) + "\n"
